"use client";

import { useEffect, useState } from "react";

type OrderItem = {
  id: number;
  order_id: number;
  product_id: number;
  quantity: number;
  unit_price: number;
  subtotal: number;
};

export default function OrderItemsPage() {
  const [items, setItems] = useState<OrderItem[]>([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/order-items")
      .then((res) => res.json())
      .then((data) => setItems(data));
  }, []);

  const totalQuantity = items.reduce(
    (sum, item) => sum + Number(item.quantity || 0),
    0
  );

  const totalSubtotal = items.reduce(
    (sum, item) => sum + Number(item.subtotal || 0),
    0
  );

  return (
    <main className="page-container order-items-page">
      <section className="page-header">
        <h1 className="page-title">Order Items</h1>
        <p className="page-subtitle">
          Teal item-level order breakdown design.
        </p>
      </section>

      <section className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon">📋</div>
          <p>Total Items</p>
          <h2>{items.length}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">📦</div>
          <p>Total Quantity</p>
          <h2>{totalQuantity}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">₹</div>
          <p>Total Subtotal</p>
          <h2>₹{totalSubtotal.toFixed(2)}</h2>
        </div>

        <div className="stat-card">
          <div className="stat-icon">🗄️</div>
          <p>Source</p>
          <h2>Supabase</h2>
        </div>
      </section>

      <section className="table-card">
        <h2>Order Items List</h2>
        <p>{items.length} records found</p>

        <div className="table-wrapper">
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Order ID</th>
                <th>Product ID</th>
                <th>Quantity</th>
                <th>Unit Price</th>
                <th>Subtotal</th>
              </tr>
            </thead>

            <tbody>
              {items.map((item) => (
                <tr key={item.id}>
                  <td>{item.id}</td>
                  <td>{item.order_id}</td>
                  <td>{item.product_id}</td>
                  <td>{item.quantity}</td>
                  <td>₹{Number(item.unit_price).toFixed(2)}</td>
                  <td>₹{Number(item.subtotal).toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </main>
  );
}